"use strict";(self.webpackChunktest_website=self.webpackChunktest_website||[]).push([[9439],{246646:(e,t,a)=>{a.r(t),a.d(t,{assets:()=>h,contentTitle:()=>s,default:()=>c,frontMatter:()=>r,metadata:()=>n,toc:()=>l});var n=a(663753),i=a(474848),o=a(28453);const r={tags:["UFO","2025-01"]},s="1955-07, London: Temothy Good \u306e\u53cb\u4eba\u304c\u5e02\u8857\u5730\u306b\u7740\u9678\u3057\u305f UFO \u306b\u906d\u9047 \u21d2 \u3053\u306e\u6b63\u4f53\u3092\u63a8\u6e2c\u3059\u308b",h={authorsImageUrls:[]},l=[{value:"\u524d\u7f6e\u304d",id:"\u524d\u7f6e\u304d",level:2},{value:"\u624b\u629c\u304d",id:"\u624b\u629c\u304d",level:2},{value:"FasterWhisper AI(large-v2 model) + DeepL(2024-07 model)",id:"fasterwhisper-ailarge-v2-model--deepl2024-07-model",level:2},{value:"\u3053\u306e\u6b63\u4f53\u3092\u63a8\u6e2c\u3059\u308b",id:"\u3053\u306e\u6b63\u4f53\u3092\u63a8\u6e2c\u3059\u308b",level:2},{value:"\u8b1b\u6f14\u52d5\u753b(1:28:37)",id:"\u8b1b\u6f14\u52d5\u753b12837",level:2},{value:"\u52d5\u753b\u6982\u8981\u6b04",id:"\u52d5\u753b\u6982\u8981\u6b04",level:3},{value:"\u8b1b\u6f14\u5168\u4f53\u306e\u6587\u5b57\u8d77\u3053\u3057",id:"\u8b1b\u6f14\u5168\u4f53\u306e\u6587\u5b57\u8d77\u3053\u3057",level:2}];function d(e){const t={a:"a",h2:"h2",h3:"h3",hr:"hr",p:"p",...(0,o.R)(),...e.components},{Details:a}=t;return a||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("Details",!0),(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)("a",{href:"/ds/img/20250102_uk_ufo_landing.jpg",target:"_blank",children:(0,i.jsx)("img",{alt:"20250102_uk_ufo_landing.jpg",border:"0",src:"/ds/img/20250102_uk_ufo_landing.jpg",width:"90%"})}),"\n",(0,i.jsx)(t.h2,{id:"\u524d\u7f6e\u304d",children:"\u524d\u7f6e\u304d"}),"\n",(0,i.jsx)(t.p,{children:"\u3053\u306e\u4e8b\u4f8b\u306f\u904e\u53bb\u8a18\u4e8b\u3067\u53d6\u308a\u4e0a\u3052\u305f\u8a18\u61b6\u304c\u3042\u308b\u3002"}),"\n",(0,i.jsx)(t.h2,{id:"\u624b\u629c\u304d",children:"\u624b\u629c\u304d"}),"\n",(0,i.jsx)(t.p,{children:"Temothy Good \u306e\u53cb\u4eba\u306e\u4f53\u9a13\u3002\u6691\u3044\u65e5\u3002\u30a8\u30f3\u30b8\u30f3\u4e0d\u8abf\u3002\u6697\u304f\u306a\u3063\u305f\u3002\u8fd1\u304f\u306b\u5225\u306e UFO \u3082\u3002"}),"\n",(0,i.jsx)(t.h2,{id:"fasterwhisper-ailarge-v2-model--deepl2024-07-model",children:"FasterWhisper AI(large-v2 model) + DeepL(2024-07 model)"}),"\n",(0,i.jsx)(t.p,{children:"\u3055\u3066\u3001\u4eba\u3005\u304c\u79c1\u306b\u5c0b\u306d\u308b\u3082\u3046\u4e00\u3064\u306e\u8cea\u554f\u306f\u3001\u306a\u305c\u3053\u308c\u3089\u306e\u3082\u306e\u304c\u6c7a\u3057\u3066\u516c\u5171\u306e\u5834\u6240\u306b\u7740\u9678\u3057\u306a\u3044\u306e\u304b\u3001\u3068\u3044\u3046\u3053\u3068\u3067\u3059\u3002\r\n\u307e\u3042\u3001\u3044\u304f\u3064\u304b\u306e\u5287\u7684\u306a\u30b1\u30fc\u30b9\u306f\u3042\u308a\u307e\u3057\u305f\u304c\u3001\u3053\u308c\u306f\u305d\u306e\u4e00\u3064\u3067\u3001\u3053\u3053\u306b\u3044\u308b\u8ab0\u3082\u304c\u77e5\u3063\u3066\u3044\u308b\u3068\u3059\u308c\u3070\u3001\u4f55\u4eba\u304b\u306f\u77e5\u3063\u3066\u3044\u308b\u3068\u601d\u3044\u307e\u3059\u304c\u3001\u307e\u308c\u306a\u30b1\u30fc\u30b9\u3067\u3059\u30021955\u5e747\u6708\u3001\u30ed\u30f3\u30c9\u30f3\u90ca\u5916\u306e\u30d9\u30c3\u30af\u30b9\u30ec\u30fc\u30fb\u30d2\u30fc\u30b9\u3067\u8d77\u3053\u3063\u305f\u3002\u578b\u3067\u306f\u83ef\u6c0f100\u5ea6\u307e\u3067\u3042\u3063\u305f\u3002\u3082\u306e\u3059\u3054\u3044\u71b1\u6ce2\u3060\u3063\u305f\u3002\r\n(0:33:55)"}),"\n",(0,i.jsx)(t.p,{children:"\u305d\u3057\u3066\u79c1\u306e\u53cb\u4eba\u304c\u3001\u5f7c\u5973\u306e\u533b\u5e2b\u3068\u5f7c\u5973\u306e\u5c0f\u3055\u306a\u606f\u5b50\u306e\u4e00\u4eba\u3068\u4e00\u7dd2\u306b\u8eca\u3092\u904b\u8ee2\u3057\u3066\u3044\u305f\u3068\u304d\u3001\u7a81\u7136\u7a7a\u304c\u6697\u304f\u306a\u308a\u3001\u8eca\u306e\u30a8\u30f3\u30b8\u30f3\u304c\u6b62\u307e\u308a\u3001\u3084\u304c\u3066\u3053\u306e\u5341\u5b57\u8def\u306b\u7740\u9678\u3057\u307e\u3057\u305f\u3002\u305d\u3057\u3066\u304b\u306a\u308a\u306e\u6642\u9593\u305d\u3053\u306b\u7559\u307e\u308a\u3001\u3084\u304c\u3066\u98db\u3073\u53bb\u3063\u305f\u3002\r\n\u79c1\u306e\u53cb\u4eba\u3001\u30de\u30fc\u30ac\u30ec\u30c3\u30c8\u30fb\u30d5\u30e9\u30a4\u304c\u4e3b\u306a\u76ee\u6483\u8005\u3067\u3059\u304c\u3001\u4ed6\u306b\u3082\u305f\u304f\u3055\u3093\u306e\u4eba\u304c\u3044\u307e\u3057\u305f\u3002\u3053\u306e\u7269\u4f53\u304c\u843d\u3061\u3066\u304d\u305f\u3068\u304d\u300110\u4eba\u304b12\u4eba\u304f\u3089\u3044\u306e\u5b50\u4f9b\u305f\u3061\u304c\u904a\u3093\u3067\u3044\u307e\u3057\u305f\u3002\u76f4\u5f84\u306f30\u30d5\u30a3\u30fc\u30c8\u304f\u3089\u3044\u3067\u3057\u305f\u3002\r\n(0:34:35)"}),"\n",(0,i.jsx)(t.p,{children:"\u305d\u3053\u306b\u3044\u305f\u4eba\u305f\u3061\u304c\u6c17\u3065\u304b\u306a\u304b\u3063\u305f\u306e\u306f\u3001\u5b9f\u306f\u3001\u307b\u3093\u306e\u6570\u672c\u96e2\u308c\u305f\u3068\u3053\u308d\u306b\u3001\u5225\u306e\u30bf\u30a4\u30d7\u306e\u98db\u884c\u6a5f\u304c\u7740\u9678\u3057\u3066\u3044\u305f\u3068\u3044\u3046\u3053\u3068\u3067\u3057\u305f\u3002\u305d\u3057\u3066\u307e\u305f\u3001\u79c1\u305f\u3061\u306f\u3001\u3053\u308c\u3089\u306e\u51fa\u6765\u4e8b\u3092\u8a93\u3046\u4eba\u3005\u306e\u58f0\u660e\u3092\u76ee\u6483\u3057\u307e\u3057\u305f\u3002"}),"\n",(0,i.jsx)("a",{href:"/ds/img/20250102_uk_ufo_landing2.jpg",target:"_blank",children:(0,i.jsx)("img",{alt:"20250102_uk_ufo_landing2.jpg",border:"0",src:"/ds/img/20250102_uk_ufo_landing2.jpg",width:"90%"})}),"\n",(0,i.jsx)("hr",{}),"\n",(0,i.jsx)(t.p,{children:"Now, another question people ask me is, why is it that these things never land in public places?\r\nWell, there have been some dramatic cases, and this is one which, if anyone here is aware of it, I'm sure a few of you are, but it's a rare case. It happened in the London suburb of Bexley Heath in July of 1955. It was up to 100 degrees Fahrenheit in type. It was a terrific heatwave.\r\n(0:33:55)"}),"\n",(0,i.jsx)(t.p,{children:"And this friend of mine was driving with her doctor and one of her small sons when suddenly the sky went dark, and there was the car engine conked out, and this thing landed at this crossroads here, eventually. And it stayed there for quite a while, and eventually it shot off.\r\nWhat my friend, Margaret Fry, was the principal witness, but there were lots of other people, there were about, I don't know, 10 or 12 children playing around at the time when this thing came down. It was about 30 feet in diameter.\r\n(0:34:35)"}),"\n",(0,i.jsx)(t.p,{children:"What the people there hadn't realized was that, in fact, another craft landed just a few streets away, a slightly different type. And again, we have witnessed statements from people swearing to these events."}),"\n",(0,i.jsx)(t.h2,{id:"\u3053\u306e\u6b63\u4f53\u3092\u63a8\u6e2c\u3059\u308b",children:"\u3053\u306e\u6b63\u4f53\u3092\u63a8\u6e2c\u3059\u308b"}),"\n",(0,i.jsx)(t.p,{children:"\u591a\u5206\u3001\u4ee5\u4e0b\u3068\u540c\u3058\u73fe\u8c61\uff08\uff1d\u5f37\u70c8\u306a EMF \u7570\u5e38\u3067\u81ea\u8ee2\u3059\u308b orb \u304c\u767a\u751f\u3057\u3001\u305d\u308c\u304c\u5927\u578b\u30b5\u30a4\u30ba\u306b\u6210\u9577\u3057\u305f\u3002EMF \u7570\u5e38\u3067\u8eca\u306e\u30a8\u30f3\u30b8\u30f3\u304c\u505c\u6b62\uff09\u3002"}),"\n",(0,i.jsx)(t.p,{children:'\u306a\u304a\u3001\u4e0b\u306e\u5199\u771f\u3092\u898b\u308b\u3068\u3001"UFO" \u306e\u4e0a\u90e8\u5074\u9762\u306b\u7a93\u304c\u3064\u3044\u3066\u3044\u308b\u3088\u3046\u306b\u3082\u932f\u899a\u3059\u308b\u304c\u3001\u305d\u308c\u3082\u5171\u901a\u3057\u3066\u3044\u308b\u3002'}),"\n",(0,i.jsxs)("blockquote",{children:[(0,i.jsx)("a",{href:"/ds/img/20200628_best_1.jpg",target:"_blank",children:(0,i.jsx)("img",{alt:"20200628_best_1.jpg",border:"0",src:"/ds/img/20200628_best_1.jpg",width:"90%"})}),(0,i.jsx)("a",{href:"/ds/img/20200628_best_2.jpg",target:"_blank",children:(0,i.jsx)("img",{alt:"20200628_best_2.jpg",border:"0",src:"/ds/img/20200628_best_2.jpg",width:"90%"})}),(0,i.jsx)("a",{href:"/ds/img/20200628_best_3.jpg",target:"_blank",children:(0,i.jsx)("img",{alt:"20200628_best_3.jpg",border:"0",src:"/ds/img/20200628_best_3.jpg",width:"90%"})}),(0,i.jsx)("a",{href:"/ds/img/20200628_best_4.jpg",target:"_blank",children:(0,i.jsx)("img",{alt:"20200628_best_4.jpg",border:"0",src:"/ds/img/20200628_best_4.jpg",width:"90%"})}),(0,i.jsxs)(t.p,{children:["ref: ",(0,i.jsx)("a",{href:"http://news21c.blog.fc2.com/blog-entry-21040.html",target:"_blank",children:"\u2751 \u753b\u50cf\u89e3\u6790\u306e\u5c02\u9580\u5bb6\u304c\u672c\u7269\u3068\u8a8d\u3081\u305f\u6700\u826f\u306e UFO \u5199\u771f \u2192 \u3053\u306e\u6b63\u4f53\u3092\u89e3\u304f \uff08\u9014\u4e2d2\uff09"})," (2023-06-23)"]})]}),"\n",(0,i.jsx)(t.h2,{id:"\u8b1b\u6f14\u52d5\u753b12837",children:"\u8b1b\u6f14\u52d5\u753b(1:28:37)"}),"\n",(0,i.jsx)(t.p,{children:"Timothy Good Secret Space Program Conference Amsterdam 2011"}),"\n",(0,i.jsx)("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/D947A38YOT0?si=espzyGvUCplFv-v3",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:!0}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.a,{href:"http://www.youtube.com/watch?v=D947A38YOT0",children:"www.youtube.com/watch?v=D947A38YOT0"})}),"\n",(0,i.jsx)(t.h3,{id:"\u52d5\u753b\u6982\u8981\u6b04",children:"\u52d5\u753b\u6982\u8981\u6b04"}),"\n",(0,i.jsx)(t.p,{children:"1,700 views 2014/04/25"}),"\n",(0,i.jsxs)(a,{children:[(0,i.jsx)("summary",{children:"\u25bc\u5c55\u958b"}),(0,i.jsx)(t.p,{children:"Worldwide research, interviewing key witnesses and discussing the subject with astronauts, military and intelligence specialists, pilots, politicians and scientists, has established Timothy Good as a leading authority on UFOs and the alien presence - the most highly classified subject on Earth."}),(0,i.jsx)(t.p,{children:"He became interested in the subject in 1955, when his passion for aviation and space led him to read a book by Major Donald Keyhoe describing UFO sightings by qualified observers such as military and civilian pilots. In 1961, after reading a book by Captain Edward Ruppelt, a U.S. Air Force intelligence officer, he began to conduct his own research. Since then, he has amassed a wealth of evidence, including several thousand declassified intelligence documents."}),(0,i.jsx)(t.p,{children:"Timothy Good has lectured at universities, schools, and at many organizations, including the Institute of Medical Laboratory Sciences, the Royal Canadian Military Institute, the Royal Geographical Society, the Royal Naval Air Reserve Branch, the House of Lords All-Party UFO Study Group, and the Oxford and Cambridge Union societies. In January 1989, following the dissolution of the Soviet empire, he became the first UFO researcher from the West to be interviewed on Russian television. He was invited for discussions at the Pentagon in 1998, and at the headquarters of the French Air Force in 2002. He has also acted as consultant for several U.S. Congress investigations. He is known to millions through his numerous television appearances and has co-produced several documentaries on the subject."}),(0,i.jsx)(t.p,{children:"UFOs remain a key military and intelligence problem -- one demanding unprecedented security and deception. Access to information is on a strictly 'need to know' basis. In 1960, former CIA director Admiral Hillenkoetter confirmed that, 'Behind the scenes, highranking Air Force officers are soberly concerned about the UFOs. But through official secrecy and ridicule, many citizens are led to believe the unknown flying objects are nonsense.' The same is still true today."})]}),"\n",(0,i.jsx)(t.h2,{id:"\u8b1b\u6f14\u5168\u4f53\u306e\u6587\u5b57\u8d77\u3053\u3057",children:"\u8b1b\u6f14\u5168\u4f53\u306e\u6587\u5b57\u8d77\u3053\u3057"}),"\n",(0,i.jsxs)(a,{children:[(0,i.jsx)("summary",{children:"\u25bc\u539f\u6587 \u5c55\u958b"}),(0,i.jsx)(t.p,{children:"So please give a warm welcome to Timothy Goode. Thank you very much, ladies and gentlemen, for that warm welcome. Now, although I'll be dealing to an extent with highly advanced technology in my presentation this morning, unfortunately we are committed to ancient technology for the presentation, the visual presentation thereof, because I still live in the 20th century regarding presentations.\r\nPowerPoint, I'm not quite up to yet.\r\n(0:01:02)"}),(0,i.jsx)(t.p,{children:"My girlfriend insists I really start soon, but there we are. She's very insistent on that. But for the meantime, there'll be slides. We did have some problems with the rented slide projector, so we just crossed fingers and hoped for the best.\r\nJust a brief overview. The fact that they say there's nothing new under the sun, I say aliens have always been here, and they've been here before we were.\r\n(0:01:45)"}),(0,i.jsx)(t.p,{children:"Many of them, not all, many of them. And it's interesting that many artists, particularly in the 13th, 14th, 15th, 16th centuries, often portrayed biblical events in terms of craft from elsewhere.\r\nThis is a 13th century French painting, and look how interesting that craft is compared to modern day sightings. This is just a nobleman on his horse pointing out to the rest of his team of riders.\r\n(0:02:38)"}),(0,i.jsx)(t.p,{children:"Here's a 15th century painting with enlargements, showing the Madonna with Saint John, and in the sky is this enlarged here, with this guy here looking up at it.\r\nIsn't that interesting? And I hope you can see, I hope it's not too over-illuminated by this powerful light here, but this is a painting by the famous Dutch painter Aert de Gelder, which I find interesting.\r\n(0:03:13)"}),(0,i.jsx)(t.p,{children:"And I think if you look at that, that is clearly a solid disk of some sort, beaming down rays of light to the infant Christ. I thought I'd have to bring in a Dutch material at some point in this talk, so that's it, probably for the rest of the morning.\r\nYou'll often hear, even in presentations by well-informed speakers, that the Americans were the first to initiate official UFO investigations.\r\n(0:03:55)"}),(0,i.jsx)(t.p,{children:"Rubbish. They started in the 1930s in Sweden. A few were in the United Kingdom, and a few were actually in America in the 1930s, when they became inundated with sightings of mystery airplanes. Very bizarre events. But the most interesting for me was that in 1933, a top-secret investigation group into unknown aerial phenomena was established by Mussolini, and they set up a top-secret team called research unit, special special research unit number 33, headed by the famous Italian engineer Marconi. And there were quite a few members of that, including astronomers, and this was a highly classified document stating that no list report of a landed vehicle on Italian soil, an landed vehicle of unknown origin, it wasn't a conventional aircraft, must not leak out to the press, and that hence this extraordinary top-secret commission was set up.\r\n(0:05:14)"}),(0,i.jsx)(t.p,{children:"And this is a very well-known violinist, certainly more well-known than I was, his name is Mussolini. Seriously, he actually was a pilot. I don't know how many of you know that. Most people wondered how on earth he could get inside the aircraft that he piloted. But at any rate, he was a talented guy, and because of his fascination with aircraft, he became immediately hooked on the UFO situation as early as 1933. And there were sightings by Royal Italian Air Force pilots, not after this event, including 1935-1936. This is a British Lancaster bomber in World War II. It was our principal bomber.\r\n(0:06:17)"}),(0,i.jsx)(t.p,{children:"Now, you've all heard about the Foo Fighters, these so-called things which appeared mostly to be remotely controlled devices which buzzed aircraft in all theaters of war, in Japan, the European theater, in the Pacific theater. I might even have a photograph of one here, but perhaps not. Now, I want to discuss the fact that not just Foo Fighters were observed in World War II, sometimes very large craft, including in one case by another Lancaster crew of a cigar-shaped object.\r\n(0:07:07)"}),(0,i.jsx)(t.p,{children:"And in this case, a sighting in 1944 over France following a bombing run. The entire crew encountered a grey disc. It was huge, they said. And this is a sketch by the radar observer showing the craft on edge. And there is the Lancaster bomber he drew for comparison. He said it was there for three minutes and then it shot off at phenomenal speed.\r\n(0:07:34)"}),(0,i.jsx)(t.p,{children:"What's interesting is that I learned, I received this letter from, via this radar observer and radio operator. He said that, the captain said, what the hell is that? The radar screen went blank and this observer in his 360 degree astrodome, as it was called, saw this thing. He said it seemed miles in width.\r\n(0:08:08)"}),(0,i.jsx)(t.p,{children:"And our Lancaster, he said, was a large aeroplane, but the only comparison I can make is that we were but a dot on a sheet of fool's paper. And after three minutes, it shot away.\r\n(0:08:15)"}),(0,i.jsx)(t.hr,{}),(0,i.jsx)(t.p,{children:"Most interestingly, the entire crew felt suffused by an unprecedented, in their case, sense of calm and well-being. What that meant, we don't know. But that is their story.\r\nNow, of course, we've had a superb presentation on the Nazis coming over here, developing the American space program, and presumably the Soviets as well.\r\nNow, many of you are aware that in 1942, the Americans tried to shoot down a large flying craft over Los Angeles. This was observed by well over a million people during a five hour air alarm.\r\n(0:09:19)"}),(0,i.jsx)(t.p,{children:"And a secret memorandum was sent to President Roosevelt by General George Marshall, United States Army Chief of Staff at that time, confirming that, you know, something like 1430 rounds of anti-aircraft shells were fired at this object, but nothing appeared to be struck or come down. And there were other objects sighted as well. But let's fast forward. In 1947, when the Americans, thanks to paperclip, were developing the V-2 program, having brought the captured V-2 rockets over to White Sand Missile Ground, from the beginning, from the inception of the space program, when these V-2 rockets were launched, on many occasions, small disks, or sometimes larger disks, were seen shooting around these rockets.\r\n(0:10:15)"}),(0,i.jsx)(t.p,{children:"And at least, on at least one occasion, one of the rockets was forced to come down prematurely by this disk. It had obviously influenced the guiding system in some way. And this was officially acknowledged at that time. This is a local newspaper in New Mexico commenting, German V-2 rocket launched at White Sands Proving Grounds Thursday afternoon, landed only six miles east of Alamogordo. The peculiar phenomena were blamed by Lieutenant Colonel Harold Turner, commanding officer of White Sands, for the, I can't read it myself, erratic test flight, I think. Is that correct? And so this was officially acknowledged.\r\n(0:11:11)"}),(0,i.jsx)(t.p,{children:"What happened then was that the Americans renewed their efforts to try and shoot down some of these flying disks. This was before they started referring to them as flying saucers, that came a little bit later.\r\nAnd they were apparently successful. My information is that a number of these craft were successfully shot down, including the ones that came down in the approximately Roswell, New Mexico area. There were other events as well.\r\n(0:11:45)"}),(0,i.jsx)(t.p,{children:"To which people respond to me, Tim, how is it possible that these craft, which are so incredibly sophisticated, would come all this way to be shot down by our primitive shells?\r\nWell, according to the aliens themselves, or at least some groups, whereas they are more than capable of handling any electronic, or remotely guided missile, or any kind of projectile shell sent at them, they were not capable of dealing with conventional anti-aircraft shells.\r\n(0:12:29)"}),(0,i.jsx)(t.p,{children:"Anyway, when the Americans started firing at these things, they retaliated, big time.\r\nThis story has really not come out properly. I have published it in my book, Need to Know, thanks to a great deal of information provided for me by Andy Kistner, a former representative for Las Cruces, New Mexico, and an engineer with an aerospace background, and he did a tremendous amount of research, and very kindly provided the results of his research to me.\r\n(0:13:09)"}),(0,i.jsx)(t.p,{children:"It indicates that there were many hundreds all over the world of mysterious accidents, not just involving military aircraft, but airliners, some of which, with, you know, ordinary passengers on board, were sometimes unable to take off, becoming... they could not unstick from the runway, and they crashed at the end with large losses of life. This was retaliation by some alien craft, and it went on for quite a time, and there has been a conflict situation ever since.\r\n(0:13:47)"}),(0,i.jsx)(t.p,{children:"All this was happening, this is just in one story, worldwide series of disastrous crack-ups, not just United States, worldwide. Planes like, for example, fighter planes that were flying in formation suddenly seemed to be thrown together, so that the whole lot crashed together.\r\n(0:14:09)"}),(0,i.jsx)(t.hr,{}),(0,i.jsx)(t.p,{children:"And of course Roswell, I'm not going to go into that, you all know everything that there is to mean, I'm quite sure. We know that, first of all, there was an official press release to the effect that the Roswell Army airfield had recovered a flying disc. And then the next day, of course, it created tremendous excitement worldwide, and the next day General Ramey said, oh it's absolute nonsense, it was just a balloon.\r\n(0:14:46)"}),(0,i.jsx)(t.p,{children:"And that is the official position of the United States government to this day, despite the fact there isn't anything to support that ridiculous theory.\r\nSo, why did they insist on a cover-up at this time?\r\nThis is General Clements McMullan. He was deputy commander of strategic air command at the time, and he was partly responsible for the balloon cover story.\r\n(0:15:18)"}),(0,i.jsx)(t.p,{children:"But this is what he said, according to Brigadier General DuBose, he said, we'd just gone through a world war, we had seen the firebombing of great cities, atomic bombs, destruction on an unprecedented scale, then came this flying saucer business. It was just too much for the public to have to deal with.\r\nWell, how thoughtful.\r\n(0:15:49)"}),(0,i.jsx)(t.p,{children:"I can see their point, but at some level, you can rest assured the military were absolutely frantic about what was going on, even if they didn't admit as much.\r\nMany of you will not be familiar with the testimony of a Polish biophysicist, who in 1974, together with a small international team, British scientist, French scientist, and an Italian scientist, and this Polish biophysicist, they were all biophysicists, liaising with NASA, and they were given, they had been given by NASA in 1974, actual pieces from an alien captured craft.\r\n(0:16:33)"}),(0,i.jsx)(t.p,{children:"They weren't told what it was, but they all came to the same conclusion when they performed tests on this thing. Phenomenal metal, for example, that melting point was well above 2000 degrees Celsius, and so on and so forth. And they were told that these bits came from the Iron Curtain. In 1977, they were invited to the Jet Propulsion, NASA's Jet Propulsion Center in Pasadena, California. And there, they were shown these remains of one or more of the small creatures that were found, and it doesn't say where.\r\n(0:17:16)"}),(0,i.jsx)(t.p,{children:"They were told one of two incidents in New Mexico, and it was obviously the skeletal structure of a small creature they give quite an amount of information that they learned, for example, that there had been one survivor, at least in one of these two incidents in New Mexico. They found their blood was similar to ours, but showed a totally different reaction toward oxygen.\r\n(0:17:55)"}),(0,i.jsx)(t.p,{children:"So, nitrogen was no good for them. So, therefore, they assumed that they must breathe a mixture of helium and oxygen on board their craft. Why do you think it is that there was a massive buildup of sightings during and following World War II? I'm sure many of you will know the answer. I think you're correct.\r\n(0:18:30)"}),(0,i.jsx)(t.p,{children:"We were not only developing atomic bombs, but we were fast developing hydrogen bombs. And in 1948, a previously secret Project Sign report, American report, stated as follows, such a civilization might observe that on earth we now have atomic bombs and are fast developing rockets. In view of the past history of mankind, they should be alarmed, and we should therefore expect, at this time above all, to behold such visitations.\r\n(0:19:14)"}),(0,i.jsx)(t.p,{children:"This is part of a top secret United States Air Forces Europe document relating to discussions with their Swedish counterparts.\r\n(0:19:26)"}),(0,i.jsx)(t.hr,{}),(0,i.jsx)(t.p,{children:"And some of the information in the second paragraph, in particular, is very interesting. The Swedes thought that some reliable and fully technically qualified Swedes have reached the conclusion that these phenomena are obviously the result of a high technical skill which cannot be credited to any presently known culture on earth. They are therefore assuming that these objects originate from some previously known or unidentified technology, possibly outside the earth.\r\n(0:20:12)"}),(0,i.jsx)(t.p,{children:"I think many of you are familiar with the Canadian government scientist and engineer, Wilbert Smith, who in a top secret Canadian government document stated that the matter is the most highly classified subject in the United States government, rating higher even than the hydrogen bomb. Flying saucers exist. Their method of operation, modus operandi, is unknown, but concentrated effort is being made by a small group headed by Dr. Vannevar Bush. The entire matter is considered by the United States authorities to be of tremendous significance.\r\n(0:20:55)"}),(0,i.jsx)(t.p,{children:"And indeed, it was significant that a small group was to be headed by Vannevar Bush because he was one of the prime movers of the project, the Manhattan Engineering District, that was the code name, project to develop the world's first nuclear weapons.\r\nAnd I can tell you that even, not just at that time, but ever since that time, the concentration of effort studying and controlling this subject resides in those who deal with the nuclear business.\r\n(0:21:39)"}),(0,i.jsx)(t.p,{children:"This is another top secret document, which you might not be familiar with, from Wilbert Smith, the Canadian scientist and engineer. They were talking about, they want to get clearance for Smith to visit the appropriate service in the United States to discuss the use of terrestrial magnetic forces in relation to aerodynamic problems associated with saucer-shaped objects. And Wilbert Smith's source for the information about the supreme high secrecy of the subject and the fact that it was all very real was given to Smith by Dr. Robert Sarbucker. This is a Canadian flying saucer.\r\n(0:22:29)"}),(0,i.jsx)(t.p,{children:"You're probably familiar with the so-called Avrocar. This is one of John Frost's special groups. This is the special projects group that actually handled this thing. Some people say it was a prototype of a flying saucer, others say it was deliberately constructed so as to let the American and other countries, presumably public, know that, you know, they're ours, really, that you're seeing. We don't know.\r\n(0:22:56)"}),(0,i.jsx)(t.p,{children:"Except that, how many of you have seen this photograph? Anybody here?\r\nI don't think I saw a hand. You did? You've seen it? You've not seen it? Maybe. Possibly. Okay. We don't know anything about this thing except that it was produced by Avro Canada. We don't know who this guy is here.\r\n(0:23:31)"}),(0,i.jsx)(t.p,{children:"I don't even know if it flew or not. But it's interesting that they actually used a canopy which is, well, it's actually lifted from an F-86 Sabre jet, which I find intriguing. I'd love to know what the control systems were and exactly what it was propelled by, if it ever flew. Now, I'm always asked how I became interested in flying saucers. Well, in 1955, I was given a book on the subject by an American cousin.\r\n(0:24:13)"}),(0,i.jsx)(t.p,{children:"And this was the book he gave me, The Flying Saucers of Eel, by Major Donald Kehoe. And I was immediately hooked. I knew nothing about the subject, but I've always been passionate about aviation and space travel. I mean, I used to get adult flying magazines when I was 10 years old, regularly. I used to go to air shows like Farnborough and so forth.\r\n(0:24:37)"}),(0,i.jsx)(t.p,{children:"And I was immediately hooked on the fact that so many reports were coming from pilots, military pilots, airline pilots, supported by air traffic controllers, which means radar, of course. And then in 1961, while I was a student at the Royal Academy of Music, I started to do my own serious research. This was after reading Captain Edward Ruppelt's book, called The Report on Unidentified Flying Objects. Ruppelt was an intelligence officer at the Pentagon, and he came out in that book, taking quite a risk at that time, saying it was all very real, they were here, and that some of them had been shot at, and so on and so forth.\r\n(0:25:22)"}),(0,i.jsx)(t.p,{children:"Now, one of the many problems associated with our subject are the hundreds, if not thousands, of missing aircraft and pilots. This one, in particular, has always intrigued me.\r\n(0:25:47)"}),(0,i.jsx)(t.hr,{}),(0,i.jsx)(t.p,{children:"1953, at Otis Air Force Base, an F-96 Starfire was scrambled to investigate a flying saucer over the airbase. This was happening every day in the 1950s, and many of the cases were reported in local and sometimes national newspapers. Well, the pilot and the radar observer in the rear took off.\r\n(0:26:19)"}),(0,i.jsx)(t.p,{children:"They got to about 11, 1200 feet. They got approaching this disc, which was hovering over the base, when everything conked out. Engine stopped, electronic power failure, the whole lot. The plane started dropping. They had to get out. Well, in theory, the radar observer is supposed to jump out first, then the captain. I don't know whether that's a naval custom, tradition carried on with the United States Air Force. But anyway, in this case, the captain jumped out because there was some struggle with the back there, with the back seater, as they sometimes call them.\r\n(0:26:59)"}),(0,i.jsx)(t.p,{children:"Right. The pilot landed safely. Thank heavens his parachute opened just in time. And he expected fully to see his radar observer land not that far from him.\r\nHe never saw the radar observer or his parachute or the aircraft. The aircraft did not crash.\r\nIt disappeared. It was never found. Neither was the radar observer. The only thing apart from the pilot that came down was the radar canopy, which of course has to be ejected prior to the pilot's ejection. Now, I obtained these figures indirectly.\r\n(0:27:43)"}),(0,i.jsx)(t.p,{children:"I didn't get them directly, but they were obtained by a very fine researcher in South America, in Brazil at the time, actually. And he had asked for an accident breakdown of accidents to aircraft from 1952 to 1956. All right. And just involving Air Force and Navy planes. All right. Of this astonishing total of 18,662 accidents during that period, most involved fast new jets.\r\n(0:28:25)"}),(0,i.jsx)(t.p,{children:"This is what I've written here, such as those scrambled in UFO interceptions, of which 56% were found to be caused by pilot error, 8% approximately by ground crew or other personnel failure, 23.4% by failure of parts and equipment in the aircraft, 2.8% by various unsafe conditions, and 9.5%, 1,773 due to unknown factors. So that is officially admitted. Doesn't mean to say they were aliens from outer space, but unknown factors of mysterious disappearances and accidents.\r\n(0:29:06)"}),(0,i.jsx)(t.p,{children:"Now, people often ask me, why is it that, you know, so few people in governments or the military come forward and discuss their sightings? Well, increasingly, I think you're well aware that they are beginning to do so. Certainly not politicians, but quite a number of military people have come forward. One or two politicians actually have indeed come forward, but this is Air Marshal Sir Peter Horsley, who I knew. He was a decorated war hero.\r\n(0:29:46)"}),(0,i.jsx)(t.p,{children:"He, at the time, this was in 1954, the time he was working as an equerry, kind of military attach\xe9 for the Duke of Edinburgh, and he worked also for the Queen in Buckingham Palace for a seven-year period at this time, when a British Army General arranged for Sir Peter, who had been working on the UFO problem in the Ministry of Defence, arranged for Sir Peter to meet an alien being in the middle of London. And Sir Peter Horsley went to this meeting place in Chelsea in London, there was another witness there, and he met this immaculately suited guy, and for the two-hour meeting, a great deal of information was given.\r\n(0:30:31)"}),(0,i.jsx)(t.p,{children:"And Sir Peter told me that the most disturbing aspect of this meeting was the fact that this alien being, who looked very human, could not only read his, Sir Peter's, mind, but he knew all Britain's top secret nuclear secrets.\r\n(0:30:56)"}),(0,i.jsx)(t.hr,{}),(0,i.jsx)(t.p,{children:"And a lot of information was given. I rather like some of the comments he made.\r\nEarth, after all, is a galactic backwater inhabited by only half-civilized men, dangerous even to their neighbours.\r\nThey said they had highly developed mental powers, including telepathy, hypnosis, and the ability to use different dimensions.\r\nThis is, of course, President Eisenhower. Some of you may have heard of his meeting in February of 1954 with extraterrestrials at Edwards Air Force Base, California, and quite a few dignitaries were there with him who have been named, and who have come forward to support this story.\r\n(0:32:00)"}),(0,i.jsx)(t.p,{children:"What is less known is that a year later, another meeting was arranged, and this took place at Holloman Air Force Base in New Mexico. And this information, it came to me from Art Campbell. You can Google him and you can read a lot about this case.\r\nAnd anyway, Eisenhower supposedly went on a top secret trip in Air Force One, and the excuse was he was going for some quail hunting with one of his high-ranking chiefs of staff or whatever, and there was quite a plane full of various journalists and so forth.\r\n(0:32:53)"}),(0,i.jsx)(t.p,{children:"And in fact, there was a meeting and a number of witnesses have come forward, like a chap, a telephone engineer working at the base who actually saw the craft come down. It came right over the telegraph pole, and he beat a hasty retreat down with his special climber. And then the thing eventually came on the ground, hovered low at first, and the meeting took place in the craft by all accounts of the witnesses there.\r\n(0:33:16)"}),(0,i.jsx)(t.p,{children:"Now, another question people ask me is, why is it that these things never land in public places?\r\nWell, there have been some dramatic cases, and this is one which, if anyone here is aware of it, I'm sure a few of you are, but it's a rare case. It happened in the London suburb of Bexley Heath in July of 1955. It was up to 100 degrees Fahrenheit in type. It was a terrific heatwave.\r\n(0:33:55)"}),(0,i.jsx)(t.p,{children:"And this friend of mine was driving with her doctor and one of her small sons when suddenly the sky went dark, and there was the car engine conked out, and this thing landed at this crossroads here, eventually. And it stayed there for quite a while, and eventually it shot off.\r\nWhat my friend, Margaret Fry, was the principal witness, but there were lots of other people, there were about, I don't know, 10 or 12 children playing around at the time when this thing came down. It was about 30 feet in diameter.\r\n(0:34:35)"}),(0,i.jsx)(t.p,{children:"What the people there hadn't realized was that, in fact, another craft landed just a few streets away, a slightly different type. And again, we have witnessed statements from people swearing to these events.\r\nIt's interesting that, publicly, General MacArthur, Douglas MacArthur, acknowledged the dangers represented by some of these beings from elsewhere.\r\nGeneral MacArthur said he described himself as a confirmed optimist regarding the possibility of another world war.\r\n(0:35:24)"}),(0,i.jsx)(t.p,{children:"And the mayor here, the mayor of New York, was saying he thinks that another war will be double suicide and that there is enough sense on both sides of the iron curtain to avoid it. He believes that because of the developments of science, all the countries on earth will have to unite to survive and to make a common front against people from other planets.\r\n(0:35:43)"}),(0,i.jsx)(t.p,{children:"Now, talking about the German scientists, this is Hermann Oberth, who, in fact, taught Werner von Braun, who was a prot\xe9g\xe9 of his. I took this picture in Germany in the 1970s. I went round for coffee and cakes. I had a delightful afternoon and later on I invited him to a concert that we were giving at the time of the London Symphony Orchestra in Nuremberg. And he lived near Nuremberg at the time.\r\n(0:36:24)"}),(0,i.jsx)(t.p,{children:"It's very interesting that he has gone on the record as saying we cannot take the credit for our record advancement in certain scientific fields alone. We have been helped, he stated. When asked by whom, by a reporter, he replied, the people of other worlds.\r\n(0:36:40)"}),(0,i.jsx)(t.hr,{}),(0,i.jsx)(t.p,{children:"And Werner von Braun, who I did not meet, in referring to the deflection from orbit of NASA's Juno 2 rocket in 1959, stated, we find ourselves faced by powers which are far stronger than we had hitherto assumed and whose base is at present unknown to us. More I cannot say at present.\r\nWe are now engaged in entering into closer contact with those powers.\r\n(0:37:15)"}),(0,i.jsx)(t.p,{children:"This is Gordon Cooper. Now, in the old days, Gordon Cooper said, you know, only a few astronauts have spotted things, but there's nothing really much in it. But in his autobiography, he describes the landing of a flying disk at Edwards Air Force Base in 1957. And at the time, Cooper was assigned as test pilot and manager with a top-secret security clearance of the fighter section experimental flight test engineering division.\r\n(0:37:59)"}),(0,i.jsx)(t.p,{children:"And his camera crew came running in to tell him exactly what had happened. They said a saucer flew over them, hovered over the ground, extended three landing gears, and set down metallic silver in color and shaped somewhat like an inverted plate. They'd shot images with 35 mil and four by five still cameras as well as motion picture film.\r\n(0:38:21)"}),(0,i.jsx)(t.p,{children:"When they tried to approach the saucer to get a closer shot, it lifted up, retracted its gear, and climbed straight out of sight. Later on, there was a United Nations, several meetings, United Nations, there was a meeting in Miami, for example, of a special political committee headed by the security general, Kurt Waldheim, to discuss the UFO question.\r\nAnd at that, at that meeting, Cooper went on the record as saying that we're going to need, we need a top-level coordinated program to scientifically collect and analyze data from all over the world, and to determine how best to interface with these visitors in a friendly fashion. And in addition to having sighted these things and chased them in in saber jets in Germany with US Air Forces Europe 1951, he actually had a much more interesting sighting, and this was divulged in an interview, a recorded interview, in about 1970, something like that.\r\n(0:39:31)"}),(0,i.jsx)(t.p,{children:"Sorry, 1974. I myself have encountered some of their craft while flying in space, he told this reporter. NASA knows this, and the American government knows it too, yet they continue to keep their silence, probably in order to avoid confusing the public. For many years, I've lived with a secret, in a secrecy imposed on all specialists in astronautics. I can now reveal that every day in the USA, our radar instruments capture objects of form and composition unknown to us.\r\n(0:40:14)"}),(0,i.jsx)(t.p,{children:"I was furthermore a witness to an extraordinary phenomenon which happened a few months ago in Florida, where he lived at the time, at his home. I saw with my own eyes a defined area of ground being consumed by fire, with four indentations left by a craft which had descended in the middle of a field. Beings had left the craft. There were other traces to prove this.\r\n(0:40:34)"}),(0,i.jsx)(t.p,{children:"They seemed to have studied the topography. They'd collected soil fragments.\r\n(0:40:39)"}),(0,i.jsx)(t.hr,{}),(0,i.jsx)(t.p,{children:"Flying saucers are a reality, continued Cooper. I won't stop repeating this. The public must be prepared to make contacts with people who sooner or later will be compelled to interfere. The salvation of us all depends on it. Now, during my correspondence with Gordon Cooper, he neither confirmed nor denied the statements attributed to him, contained in this interview. In a letter to Ambassador Griffith at the United Nations, Gordon Cooper made an interesting statement in which he said, I have not yet had the privilege of flying a UFO. Now, just a few years ago, a respected colleague informed me that following the United Nations meetings in 1974 and 78, the General Assembly in 1978, Cooper had vented his frustration at the seemingly invincible task of convincing the United Nations delegates of alien reality. What would it take, he said to this researcher friend of mine, a landed flying saucer.\r\n(0:41:56)"}),(0,i.jsx)(t.p,{children:"He then went on to claim that he himself was in a position to actually pilot a flying disc and land it himself. An outrageous claim, to be sure, but from other reliable sources, I have heard that a number of astronauts and pilots, not just in the United States, have learned to fly alien and or alien replicated craft and it's been going on for quite some time.\r\n(0:42:29)"}),(0,i.jsx)(t.p,{children:"Yes, this is Buzz Aldrin. How many of you are aware that he acknowledged officially that Apollo 11 was buzzed on its way to the moon?\r\nBuzz Aldrin, he actually said that, if I can find the statement here, maybe not, he said there was something out there that was close enough to be observed. Mike Collins, was one of the three Apollo 11 astronauts, decided he thought he could see it in the telescope.\r\n(0:43:05)"}),(0,i.jsx)(t.p,{children:"When you made it real sharp, it was sort of bell-shaped. Obviously, the three of us weren't going to blurt out, hey, Houston, we've got something moving alongside of us and we don't know what it is. We weren't about to do that because we knew that those transmissions would be heard by all sorts of people.\r\n(0:43:23)"}),(0,i.jsx)(t.p,{children:"And who knows, somebody would have demanded we'd turn back because of aliens or whatever. Well, it gets better. Two Soviet scientists confirmed that there were large alien craft on the moon during the actual landing. This was confirmed by Soviet scientist Dr. Alexander Kazentsev, who claims that Buzz Aldrin had actually taken color movie film of the spacecraft from inside the module and continued filming them after he and Armstrong went outside.\r\n(0:43:57)"}),(0,i.jsx)(t.p,{children:"They were large, mysterious objects, watching them after they'd landed in the lunar module. In Above Top Secret, I cited the testimony of a good friend of mine who'd participated at a NASA conference in Italy in June 1984, during which she learnt, she overheard in the next room Neil Armstrong discussing what had happened actually on the moon with a German professor, NASA professor.\r\n(0:44:34)"}),(0,i.jsx)(t.p,{children:"And my source has passed away now, I can, I'll just give you her first name though, Pamela. And she'd served with Britain's secret intelligence service, popularly known as MI6. She said that, the actual, she quotes, she made notes immediately afterwards as best she could of exactly what was said. Professor, what really happened out there? Armstrong. It was incredible.\r\n(0:45:02)"}),(0,i.jsx)(t.hr,{}),(0,i.jsx)(t.p,{children:"Of course, we'd always known there was a possibility. The fact is, and he gives the name of the professor, we were warned off. There was never any question of a space station or a moon city. And the professor says, how do you mean warned off? I can't go into detail, said Armstrong, except to say that their ships were far superior to ours, both in size and technology.\r\n(0:45:25)"}),(0,i.jsx)(t.p,{children:"Boy, were they big and menacing. No, there's no question of a space station. Professor responds, but NASA had other missions after Apollo 11. Naturally, replied, replied Armstrong, NASA was committed at that time and couldn't risk a panic on earth. But it really was a quick scoop and back again.\r\nNow, at a cocktail party later that evening at the NASA space conference, Pamela confronted Armstrong, who confirmed that the story was true, but refused to go into further detail beyond admitting that the CIA was behind the cover-up. She added, I asked her years later if she stood by this claim, and she said, I still stand by the Armstrong report.\r\n(0:46:17)"}),(0,i.jsx)(t.p,{children:"Like Martin Luther, I can do no other. Perfectly placed as I was in the next suite. And in light of the cover-up the United States still has in place, it surprises me not that Neil Armstrong denies it. She added that the United States has had contact since the early 1960s with a superior extraterrestrial race.\r\nNeil Armstrong. There he is.\r\n(0:46:59)"}),(0,i.jsx)(t.p,{children:"This is an interesting photograph on the moon. It's supposed to be the color-wise and clarity-wise the best that NASA could produce. And they were prints covered with a special sort of plasticized material to stop them ever ever changing color. And I still have this framed picture at home showing the Schmidt crater, which is towards the other side of the moon. And you can see the interesting color.\r\n(0:47:25)"}),(0,i.jsx)(t.p,{children:"Does it not have a sort of moss-like color, would you agree? NASA said, oh no, that they were using the wrong type of film or something.\r\nAstronauts don't use the wrong type of film and they're very careful the way they develop slide material. This was taken with Ektachrome. Now, many of you will have heard of Philip Corso, who was as chief of the Army's, United States Army's foreign technology division, actually stewarded the engineering, the remarkable advanced engineering materials to the American industrial corporate giant.\r\n(0:48:08)"}),(0,i.jsx)(t.p,{children:"Alien artifacts, integrated circuit chips, fiber optics, lasers, super tenacity fibers, and so forth.\r\nWhat is less known about Corso, and he didn't write about it in his book, The Day After Roswell, is that in 1957, when he was in charge of the Army's firing site, missile firing range, at White Sands, he was, he had a very strange experience in which he was in a plane, a small plane, Army plane, flying over a certain area in White Sands when he saw what looked like a disk on the desert ground.\r\n(0:48:52)"}),(0,i.jsx)(t.p,{children:"He didn't, he assumed it was a missile booster. It was a shiny saucer-shaped object, he said, at any rate. Later he visited the site, nothing to be seen, he said, but suddenly it materialized back and forth on the ground.\r\n(0:49:05)"}),(0,i.jsx)(t.hr,{}),(0,i.jsx)(t.p,{children:"You could see it sometimes very, very clearly, and other times it became invisible.\r\nWell, he chucked a rock at it on two occasions, and it obviously hit the thing because it bounced off. And a long story short, it took off, affecting his, the engine of his truck.\r\nAnd he later on communicated telepathic, this was several weeks later, with a being of the so-called grey variety, wearing a type of helmet.\r\n(0:49:40)"}),(0,i.jsx)(t.p,{children:"And the purpose of this meeting was because in order for these missiles to be fired, they had to have what was called green time.\r\nAnd Corso has referred to this, when they turn off the radar in case of interference to the missiles being tested. And this alien requested telepathically green time, would Corso ask for them to turn off the radars while they took off, and Corso managed to get the agreement of his colleagues. He was in charge after all, so that's happening.\r\n(0:50:14)"}),(0,i.jsx)(t.p,{children:"A lot of people have said, oh, you don't want to take Corso seriously. I know a lot of distinguished researchers, just so you know. I could mention one famous researcher who says, no, no, Corso, no, he says he was in the National Security Council. That's rubbish, that's absolutely rubbish, he's lied. I said to the chap, well, have you actually seen the military records of that time? And here they are, I managed to get these.\r\n(0:50:46)"}),(0,i.jsx)(t.p,{children:"Corso was on the intelligence staff for a number of years at the operations, Special Operations Coordinating Board, which is attached to the National Security Council. And therefore, he, Corso, and anyone attached to the Special Operations Board, later known as the Special Group, would have had access to the most sensitive information dealt with by the intelligence community. He was attached to the National Security Council intelligence staff.\r\n(0:51:19)"}),(0,i.jsx)(t.p,{children:"In 1961-62, I was given information by a man who knew Kennedy that Kennedy had requested seeing the alien bodies and craft, and he was duly granted access.\r\nTo that extent, he was taken on a top-secret flight, so of course, you know, people would say, well, there's no record, Tim, you know, there's no record of Air Force One leaving. Well, you know, when you've got a top-secret mission, you don't sort of get these things in freedom of information act requests.\r\n(0:52:00)"}),(0,i.jsx)(t.p,{children:"You don't get that kind of information. And that will remain top secret to this day. But apparently, the general in charge was General McHugh, Godfrey T. McHugh, and he took to a special Air Force base, homestead Air Force base in Florida, and was shown craft and bodies. I don't know any more than that.\r\nJust a photograph, can't see very clearly, but I always show this picture because people say, well, you know, so many pictures are not clear, and admittedly, we could probably have some less light and see it better, but it's a flying disc, shadow on the ground.\r\n(0:52:44)"}),(0,i.jsx)(t.p,{children:"This is, thank you very much, this is a highway in the jungle in Venezuela. This is all jungle. There's the shadow of the aircraft, there's the shadow of a DC-4 airliner, and there is the nacelle, the propeller spinner of one of the engines. And the photograph was taken by the first officer, sitting in the right-hand seat, obviously. And people have said, oh yes, it was a button on the cockpit canopy. I don't think so.\r\n(0:53:12)"}),(0,i.jsx)(t.p,{children:"Furthermore, professional topographers and mathematicians determined that all the shadows tallied with the objects depicted in the sky.\r\n(0:53:24)"}),(0,i.jsx)(t.hr,{}),(0,i.jsx)(t.p,{children:"I want to mention George Adamski, much maligned in many ways. A lot of the stories he came out with seemed bizarre, but I've learned, also from my own experiences, that a lot of what he said was true. One can quibble with whether the beings he encountered were actually Martians and Venusians, as he, interestingly, referred to them as Venetians, or Saturnians, which doesn't inspire confidence. But what I can tell you about this man is that he was treated with remarkable seriousness by the intelligence community and by the political community.\r\n(0:54:14)"}),(0,i.jsx)(t.p,{children:"And he, in fact, held a United States government ordinance pass, which gave him access not just to any American Air Force base in the States, but abroad as well. He was very well connected. He met Kennedy on several times, and he arranged for Kennedy to be taken on board a craft in 1963. I think it was in May of 1963. And he was involved in all sorts of arrangements for various people to meet the so-called space people, as he referred to them sometimes.\r\n(0:54:54)"}),(0,i.jsx)(t.p,{children:"He also had not one, but two meetings with Pope John XXIII at the Vatican shortly before the Pope passed away. You may have heard of one of them. I've written about it, but there was another one which has yet to come to life, apart from what I've told you.\r\n(0:55:16)"}),(0,i.jsx)(t.p,{children:"I don't know any more than that. And this is a frame from an 8mm movie film, taken by Adamski in the presence of Madeleine Rodifer, who passed away a few years ago, a very dear friend of mine. She was there. There were two people from the United States government present who were liaising with the aliens in the craft, which, according to an optical physicist, was 27 feet in diameter.\r\n(0:55:44)"}),(0,i.jsx)(t.p,{children:"And the craft displayed a series of jerky movements like that, and these things underneath, they're not landing gear by the way, they hold a certain substance, which is related specifically to the propulsion system, and these things were sort of going up and down and changing shape and so forth. And interestingly, there is always a distortion in the craft in the direction it's heading, as if something is arranged gravitational-wise. A gravitational field is created and this is what causes optical distortions in the atmosphere. The craft itself does not change shape.\r\n(0:56:21)"}),(0,i.jsx)(t.p,{children:"Now, in 1998, I was invited by this man, General Kenneth Israel, who at that time was director of the Airborne, Defense Airborne Reconnaissance Office, which is now, really, well, it's parceled in with the National Reconnaissance Office altogether, but this was the Defense Airborne Reconnaissance Office, which at that time handled the unmanned spy planes.\r\nAnd I was invited to the Pentagon for a half-hour meeting, it wasn't classified, there was even a sign outside saying, no classified here, but a welcoming sign for me and everything.\r\n(0:57:15)"}),(0,i.jsx)(t.p,{children:"I was expecting a one-to-one with the General. However, there were about a total of, I'd say, about 12 people in the room, mostly young members of this organization from all the various military services that were working with Daro. Now, during that meeting, General Israel made it quite clear to me that he believed that film, taken in Washington, DC, in February 1965, was absolutely genuine.\r\n(0:57:39)"}),(0,i.jsx)(t.p,{children:"And Adamski wasn't the only person to film these things. There are lots of fairly good photographs. This is an extreme enlargement of another bell-shaped craft, as they're sometimes referred to. Slightly different from the Adamski one, but a certain similarity nevertheless. Now, I want to discuss with you, I'm just going to see if I can tighten up on the focus a bit here, maybe a little bit, yeah, extraordinary developments in Italy and the rest of the world, as a matter of fact, but there was an organization called Amicizia, which was formed in 1956. There were many people involved from all walks of life, literally all walks of life.\r\n(0:58:40)"}),(0,i.jsx)(t.p,{children:"And somewhere here I can have information, a sort of category of people we're dealing with.\r\n(0:58:47)"}),(0,i.jsx)(t.hr,{}),(0,i.jsx)(t.p,{children:"This saga, because I can only describe it really as a saga, lasted 40 years at least. It involved a large group of people in many countries, such as Argentina, Austria, Chile, France, Germany, Italy, Siberia, Switzerland. The preliminary contacts were in 1956. And one of the early contactees was this professor, Bruno Sammaciccia, a well-known and respected Catholic historian.\r\n(0:59:29)"}),(0,i.jsx)(t.p,{children:"This is Stefano Breccia, who I know and have met on several occasions. This was a photograph of him taken at the time these contacts took place. He said, all of us were moved by the deep morality and sincere humanity on the part of the aliens, he says. These were people who simply could not imagine doing anything evil to anyone, who liked eating well, drinking wine, even smoking, who enjoyed playing the violin, in one case, and tennis, and driving luxury cars and executive aircraft.\r\n(1:00:03)"}),(0,i.jsx)(t.p,{children:"They lived most of the time in their huge underground bases, but some of them lived among us, inside our society.\r\nOne of these aliens that was liaising here became a university researcher, another the manager of a rather important textile company in Italy, and a third one was the senior manager of one of the largest German telecommunications companies.\r\n(1:00:30)"}),(0,i.jsx)(t.p,{children:"Everything was kept secret for decades, but there's a book out called Mass Contacts in English, which I thoroughly recommend to you.\r\nIt's a very, very confusing story. Be prepared, you have to read through a lot of it. Very confusing story, but Mass Contacts by this man, Stefano Breccio and Bruno Sammaciccia, who sadly died before the book was published.\r\n(1:00:59)"}),(0,i.jsx)(t.p,{children:"Some of the humans were hand-picked by the aliens, including this man here, Stefano, who is an expert in artificial intelligence and computer scientists.\r\nOthers contacted involved, for example, 20 engineers, an archaeologist, accountants, an expert in military logistics, bank employees, two members of the United Nations Food and Agriculture Organization, five university professors, a quarter of a size's judge, the executive vice president of one of the largest multinational companies in the world, and two future Nobel Prize laureates and four generals.\r\n(1:01:36)"}),(0,i.jsx)(t.p,{children:"Those were the people liaising with the aliens. This is Bruno Ghibaldi, a very respected aerospace journalist at the time, who himself had many meetings with these people in Italy. A number of these people were taken to their alien bases, which some of them were large. The largest base, underground base, was 186 miles long and 62 miles wide.\r\n(1:02:12)"}),(0,i.jsx)(t.p,{children:"And I can, maybe if we have some question time later, there were certain technology they have which makes it relatively easier to bore out huge, huge spaces underground and elsewhere. Some beautiful women are amongst them.\r\nThey sometimes have very, very small bases. There are tall, some very, very tall aliens.\r\nI'll be showing you one in a minute. This was Alberto Perego, who was a well-known diplomat at the time, who was regularly in touch with these people.\r\n(1:02:42)"}),(0,i.jsx)(t.p,{children:"And here we have Paolo Di Girolamo, a famous Italian artist who also had regular contacts and took photographs of their craft, and so forth. And here we have one of the aliens, one of the very tall ones.\r\n(1:03:02)"}),(0,i.jsx)(t.hr,{}),(0,i.jsx)(t.p,{children:"His height has been worked out from this photograph at just over 3.7 meters, well over 9 feet tall. And this photograph was taken by Bruno Sammacicci, the Catholic historian, in his garden. And tests have been done determining the exact height by knowing the height of this tree at the time, and the pine needles, and so on and so forth.\r\nSo is this the real deal? Or just an incredible hunk, as some of you might refer to?\r\n(1:03:44)"}),(0,i.jsx)(t.p,{children:"There's a great deal to the Amicizia thing, which is really absolutely stunning, and you can yourselves learn about it by getting that book, Mass Contacts. It's very muddled in style, but it's well worth it. Most of you are familiar with Britain's Roswell, 1980, when a craft came down outside the twin United States Air Force bases of Bentwaters and Woodbridge in Suffolk. And at one time, the craft, this was going on several nights, were beaming lights at the nuclear weapons storage area, where there were more nuclear weapons stored than anywhere else in Europe at that time.\r\n(1:04:39)"}),(0,i.jsx)(t.p,{children:"And the official Ministry of Defense position was that this was of no defense significance. Can you imagine? Unknown craft, one of which, the main one, landed about 15 feet long, as you can see from here. And there's another sketch I have here, made by one of the witnesses to the craft when it was sort of upended. But eventually it actually landed flat, and two of the nuclear security policemen actually touched the craft and stood on it before it shot off away in the tree.\r\n(1:05:16)"}),(0,i.jsx)(t.p,{children:"No defense significance. China. I need to mention that even as far back as 1992, this is a 1985 article talking about a UFO conference in China. As far back as 1992, China, which the UFO Research Association, was affiliated with the Science and Technology Branch, Association of Scientific and Technical Institute. And they had 3,600 formal members, as well as 40,000 research associates.\r\nMost of China's UFO researchers are scientists and engineers, and many UFO groups in China require a degree and published research for membership.\r\n(1:06:08)"}),(0,i.jsx)(t.p,{children:"I think you're familiar with Ronald Reagan's famous comment in the United Nations General Assembly in 1987. We often forget how much unites all the members of humanity.\r\nPerhaps we need some outside universal threat to make us recognize this common bond.\r\nI occasionally think how quickly our differences worldwide would vanish if we were facing an alien threat from outside this world.\r\nAnd yet, I ask, is not an alien force already among us? And he just paused for a second, then he went on to say, of course, what could be more alien to our security than the threat of possible nuclear extinction? But I think he meant something else.\r\n(1:07:07)"}),(0,i.jsx)(t.p,{children:"Now, more recently, some of you will have seen this on the web, in 1985, the June 11th entry in Reagan's diary states, had lunch with five top scientists. It was fascinating.\r\nSpace truly is the last frontier, and some of the developments there in astronomy, etc., are like science fiction, except they are real. I learned that our shuttle capacity is such that we could orbit 300 people.\r\n(1:07:47)"}),(0,i.jsx)(t.p,{children:"Now, officially, we certainly don't have shuttles, certainly not back at that time, in 1985, to orbit 300 people. So, what was he talking about?\r\n(1:07:53)"}),(0,i.jsx)(t.hr,{}),(0,i.jsx)(t.p,{children:"Gorbachev, as many of you will know, and we published this before, but some of you may not, at the Geneva Summit, Gorbachev confirms, the United States President said, if the Earth faced an invasion by extraterrestrials, the United States and the Soviet Union would join forces to repel such an invasion.\r\n(1:08:22)"}),(0,i.jsx)(t.p,{children:"I shall not dispute the hypothesis, though I think it's early yet to worry about such an intrusion. Now, this is a picture taken by Ed Walters in Florida, in the late 80s, involving Gulf Breeze, some of you are familiar with it, and I found it, I think his pictures are genuine, I spent quite a lot of time with him, I found him genuine.\r\n(1:08:47)"}),(0,i.jsx)(t.p,{children:"I find this one, for me, a craft about 15 or 16 feet in diameter, taken in Gulf Breeze, I find particularly convincing.\r\nNow, yes, 10 minutes, okay, thank you, even though we went over time.\r\nYeah, we started very late, but anyway, I'll do my best.\r\nIn 1989, I was approached by the director of a special group associated with Ringling Brothers and Barnum & Bailey, who invited me to become the official consultant on UFO research to a special development group.\r\n(1:09:30)"}),(0,i.jsx)(t.p,{children:"A personal meeting in Orlando, Florida, was a prerequisite. Well, I couldn't make it, and instead I recommended my friend Bob Exler, who in fact had worked with NASA because NASA was involved in this project, very much so, and he's a former NASA engineer who'd worked on the space shuttle arm. Anyway, he got the job, and his first meetings took place in Orlando in November, beginning of November 1989, and after signing a non-disclosure agreement, he was briefed.\r\n(1:10:04)"}),(0,i.jsx)(t.p,{children:"The board advisors included former astronauts Alan Bean, Gene Cernan, Charles Conrad, Alexei Leonov, Tom Stafford, and had the approval of President George Bush, Vice President Dan Cahill, and the National Space Council, and so forth. And they were going to have a 15,000 square foot traveling space exhibition with 6,000 square feet of UFO-related information.\r\nAnd it was to involve many schools in the United States, it was going to travel worldwide. Well, Bob was sent to the Pentagon in 1989, and he reported to General Stafford, who was the intelligence contact for this, and during that meeting, Stafford talked about presenting things, they talked about all sorts of things, about the shuttle and so forth, but he said, you know, we're thinking of presenting either a facsimile or an actual recovered alien vehicle, and to show some bodies in a cryogenic tank.\r\n(1:11:09)"}),(0,i.jsx)(t.p,{children:"But you know, he asked Bob whether he thought, you know, that you should just have model substitutes rather than the real thing, and asked Bob's opinion. Bob said, yeah, let's get the real thing.\r\nSo, there we are, and it goes on and on. A great deal happened. Bob was subsequently taken to, for example, a microgravity chamber area at Ellington Field, NASA Ellington Field in Houston, where he was actually involved in microgravity experiments with some astronauts, including Alan Bean. He was also taken on an extremely fast helicopter to what he thought was an oil rig in the Gulf of Mexico, which turned out to be a special monitoring station for alternative spacecraft. That's how they were labeled, ASC, alternative spacecraft.\r\n(1:12:01)"}),(0,i.jsx)(t.p,{children:"And eventually, other things, other things, other strange things occurred to him. It's a long, drawn-out story. I wrote about it in my book, Alien Liaison or Alien Contact in the States. But he had some extraordinary information. I'm going to move on here.\r\n(1:12:34)"}),(0,i.jsx)(t.hr,{}),(0,i.jsx)(t.p,{children:"Later, I went to the National Space Council offices, which is adjoining the White House, in what used to be called the old Executive Office Building. And I spoke to Colonel Simon Pete Warden there. I think I was expecting... I made a special trip from the UK and all dolled up in my best suit and everything.\r\n(1:13:03)"}),(0,i.jsx)(t.p,{children:"I think I was in and out in about 10 minutes. He was very embarrassed, acutely embarrassed by the whole thing. And I said, well, you know, why was it stopped? And he said, well, the Spanish pulled out of it, you know, we couldn't get any money from them, so we decided to drop the whole thing, and so on and so forth.\r\nAnd there is the old Executive Office Building. I think it's now called the Reagan Building in DC. Now, these are actual intelligence community jokes, if you like, but with a degree of solemnness attached to them.\r\n(1:13:44)"}),(0,i.jsx)(t.p,{children:"Celestial, even celestial travel requires a defensive travel security briefing. Okay? How about this? Planning any foreign travel? Don't forget to notify your security office. This is Gennady Manikov, who together with his colleague on board the Ramiro Space Station in 1990 saw a huge silvery iridescent sphere. It was difficult to determine, he said, but the object was at a great altitude over the Earth, perhaps 20, 30 kilometers.\r\n(1:14:23)"}),(0,i.jsx)(t.p,{children:"It was much larger than a huge ship and had a regular shape, but what it was, I don't know.\r\nThis was a huge craft seen in Paris by a friend of mine, Gabrielle Grellet, France's leading UFO researcher, former Air France pilot and so forth, and fighter pilot prior to that. This is a craft that was a kilometer long over Paris, seen by him and many, many other witnesses.\r\n(1:14:54)"}),(0,i.jsx)(t.p,{children:"He was with a whole group of people, and he said it came over silently and it seemed to carry, or rather, as it came towards them, you couldn't hear anything, everything stopped. He said it's as if it carried its own zone of silence. This is a photograph taken in Italy in 1993 by Filiberto Caponi, part of a series taken over a series of months.\r\n(1:15:27)"}),(0,i.jsx)(t.p,{children:"It was only 90 centimeters in height, there was no communication, it was absolutely without any kind of hostility at all, it was in fact very, very docile. It had clearly been damaged, very injured, very badly, almost certainly burnt. No one knows the circumstances of that at all, and there was no communication, no telepathy, nothing, and on each of the occasions it appeared, it would then rush off shrieking. Very, very powerful legs, but seemingly useless arms.\r\n(1:15:59)"}),(0,i.jsx)(t.p,{children:"A huge craft seen in Canada by numerous witnesses.\r\nI have to say, I did quite a lot of investigation into the animal mutilation business, and I've been to Puerto Rico, where a lot of stuff goes on. I've been there seven times, and on one of the visits I interviewed, together with Jorge Martin, a security guard who saw an animal, a cow, being beamed up aboard a craft, at which point some American officials came along in a car.\r\n(1:16:43)"}),(0,i.jsx)(t.p,{children:"This was two o'clock in the morning, this was a security guard, had been working late, and they told him, get lost, just stay here for 15 minutes, then you can continue on your journey. Well, sure enough, he waited, he wasn't going to argue with them, and 15 minutes later he turned up, he could see that the cow had been dropped beside the road, obviously from a great height.\r\n(1:17:26)"}),(0,i.jsx)(t.p,{children:"Okay, when you learn about stories like this, I'm about to tell you, this was January 2004, an Aer Lingus Boeing 737, this actual plane, was on its final approach to Dublin airport when it was buzzed by a flying triangle, which there were dreadful shards of brilliant violet light coming from it, it caused a tremendous turbulence, it caused the plane to be damaged, the air brakes and the skin metal on the wings, and I don't know if it was an emergency landing as such, but certainly the flight crew were very, very frightened indeed, and this was observed by a plane several miles behind, and the next plane that landed at Dublin had encountered the same craft, though the problems weren't so violent as this.\r\n(1:18:09)"}),(0,i.jsx)(t.p,{children:"Here's a huge craft encountered in Tennessee, in October 2000, in Bristol, Tennessee, October 2004. He suffered nausea, vomiting, lethargy, hair loss and sunburn, and according to a friend of his I spoke to, who was familiar with finding out exactly, you can sometimes find out exactly who's following a story like this, he said Lockheed Martin Boeing and the United States government showed considerable interest in this case on the internet.\r\n(1:18:56)"}),(0,i.jsx)(t.p,{children:"The witness, Sidney, lost 15 minutes of time. He had had a recently diagnosed brain tumor, and according to my friend, it had disappeared, according to a magnetic resonance imaging scan, after this event. In Britain, in 2004, not far from the center of Cambridge, this journalist, Andy Martin of the Independent newspaper, saw a huge craft which filled the sky it appeared to be a structured craft, and he and his family saw it, and dark outline of a craft, nothing like a plane, definitely jumbo-sized, and it wasn't going up, and it wasn't coming down, and that's from a, you know, a respected news journalist.\r\n(1:19:46)"}),(0,i.jsx)(t.p,{children:"This photograph was taken in Puerto Rico, in, I think, I think it was 1997, I'm not quite sure, no, a bit later than, sorry, much more recently than that, I don't have the date with me, but I find it very, very interesting, I think it's a genuine picture.\r\n(1:20:03)"}),(0,i.jsx)(t.hr,{}),(0,i.jsx)(t.p,{children:"In 2007, two airliners in part of the British Isles, they were in the Channel Islands, in French airspace, actually, and there was one flying a Trilander here, and he's come forward and said that they saw these two craft, two mile, up to two, some of them at least a mile, two of them a mile in length, and this was confirmed by the pilot and crew and passengers of another airliner flying in the vicinity, 2007. On several occasions, British helicopter police have encountered UFOs which were on near-collision course with them, in the UK. Now, I'm sure many of you are familiar with Gary McKinnon. For him, he told me that the most important information he uncovered related to the Air Force Space Command, and he said he found a list of Air Force officers, or officers anyway, under the heading non-terrestrial officers.\r\n(1:21:23)"}),(0,i.jsx)(t.p,{children:"It doesn't mean little green men, what I think it means is not Earth-based. I found a list of fleet-to-fleet transfers, and a list of ship names.\r\nI looked them up, they weren't US Navy ships. Now, on finding the first image on his PC, Gary told me, the Earth, or at least a blue and white planet with no continents visible, filled two-thirds of the screen.\r\n(1:21:53)"}),(0,i.jsx)(t.p,{children:"Midway between the camera and the planet hung a cigar-shaped object with geodesic domes above, below, and to the left and right. I didn't see any rivets, seams, or telemetry antennae. This is Paul Hellyer, former Defense Minister during the Trudeau administration from 1963 to 1967. I'm in touch with him, I was in touch with him recently, he's sending me his book, he's written a book, which includes a lot of information about the subject. He stated, the classification was, from the outset, above top secret, so the vast majority of US officials and politicians, let alone a mere allied Ministry of Defense, were never in the loop. The United States has developed the aliens' own weapons, lasers and particle guns, to the point where they can be used against the visitors from space.\r\n(1:22:52)"}),(0,i.jsx)(t.p,{children:"I'm so concerned about what the consequences might be of starting an intergalactic war, and that's why he's chosen to speak up.\r\nBen Rich, he developed the stealth program, very old hat now, very, very old technology, believe me. Now in 1993, he gave a very important presentation at UCLA, University of California in Los Angeles, at the Department of Engineering, of which he was an alumnus.\r\n(1:23:25)"}),(0,i.jsx)(t.p,{children:"And two alumni, or actually friends of mine, two new found researchers were present. And this is what Ben Rich said in 1993, two years before he died. We already have the means to travel among the stars, but these technologies are locked up in black projects, and it would take an act of God to ever get them out to benefit humanity.\r\n(1:23:57)"}),(0,i.jsx)(t.p,{children:"Anything you can imagine, we already know how to do. And that was in 1993. Now, I know you're all expecting a presidential address, disclosure, when the president comes forth and tells you exactly what's going on. Do you seriously think, any of you, that's going to happen? If it does, I mean, who knows? I didn't make it to the White House last time, I'm afraid, but who knows? I thought she was in the running at one stage.\r\n(1:24:33)"}),(0,i.jsx)(t.p,{children:"Maybe she'll make the big announcement, you know, but do you really think we're going to be told the whole story? Do you think any politician is going to stick their neck out to tell us even half the story? I don't think so.\r\n(1:24:49)"}),(0,i.jsx)(t.hr,{}),(0,i.jsx)(t.p,{children:"This is our planet, ladies and gentlemen, it's the only one we have at the moment.\r\nI can tell you that beings from other worlds, some anyway, races, have been on this planet for longer than we have, and we are a genetic by-product. We are aliens ourselves.\r\nThe bad news is that there are many aliens coming and going here.\r\n(1:25:32)"}),(0,i.jsx)(t.p,{children:"Many of them are visiting, a lot are living here, and many of them are spiritually thousands of years or millions of years ahead of us and technologically. The bad news is that there are others coming here who, I could give you a lot of detail, maybe in question time, I've learned from someone very highly placed about what some of these other critters are up to, but they certainly seem to have evil intentions for the human race regarding a hybridization process, and so on and so forth.\r\n(1:26:15)"}),(0,i.jsx)(t.p,{children:"So in any event, I think, ladies and gentlemen, you know, it's our only planet at the moment. I can assure you there seem to be efforts to colonize us elsewhere at some point, because maybe we are heading for disaster, not just on a nuclear scale, but everything else points to the possibility. After all, there have been great inundations in the past, changes of continents and so forth.\r\n(1:26:40)"}),(0,i.jsx)(t.p,{children:"Who knows what's coming up next? Certainly the aliens will have greater knowledge about that, and maybe they're helping us. Who knows? But I will say that I think whatever threat is posed by beings from other worlds, I still fear human beings more. Anyway, it's a great planet. They all say it's unique, not in the galaxy.\r\n(1:27:21)"}),(0,i.jsx)(t.p,{children:"Obviously, it's unique in our solar system, but it's unique in this particular neck of the Milky Way galaxy, and therefore it is of immense interest to all and some.\r\nAnyway, ladies and gentlemen, I've brought lots of copies of my books along. It's a very heavy package. I do not want to take them home with me, so you need to know.\r\nYou need to know, and I need the dough. Thank you very much.\r\n(1:27:51)"}),(0,i.jsx)(t.p,{children:"Thank you very much, Mr Timothy Goode. This was very enlightening.\r\n(1:28:06)"})]}),"\n",(0,i.jsx)(t.p,{children:"(2025-01-02)"})]})}function c(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},28453:(e,t,a)=>{a.d(t,{R:()=>r,x:()=>s});var n=a(296540);const i={},o=n.createContext(i);function r(e){const t=n.useContext(o);return n.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),n.createElement(o.Provider,{value:t},e.children)}},663753:e=>{e.exports=JSON.parse('{"permalink":"/ds/blog/2025/01/02/uk_ufo_landing","source":"@site/blog/2025-01-02-uk_ufo_landing.md","title":"1955-07, London: Temothy Good \u306e\u53cb\u4eba\u304c\u5e02\u8857\u5730\u306b\u7740\u9678\u3057\u305f UFO \u306b\u906d\u9047 \u21d2 \u3053\u306e\u6b63\u4f53\u3092\u63a8\u6e2c\u3059\u308b","description":"\u524d\u7f6e\u304d","date":"2025-01-02T00:00:00.000Z","tags":[{"inline":false,"label":"UFO","permalink":"/ds/blog/tags/UFO","description":"UFO \u95a2\u9023"},{"inline":false,"label":"2025-01","permalink":"/ds/blog/tags/2025-01","description":"2025-01"}],"readingTime":60.05,"hasTruncateMarker":true,"authors":[],"frontMatter":{"tags":["UFO","2025-01"]},"unlisted":false,"prevItem":{"title":"Bart Ehrman : \u4e09\u4f4d\u4e00\u4f53\u306f\u4e0d\u5408\u7406\u3001\u305d\u308c\u3086\u3048\u7406\u89e3\u4e0d\u80fd\u3060","permalink":"/ds/blog/2025/01/02/be_5"},"nextItem":{"title":"Bart Ehrman : \u30a4\u30a8\u30b9\u306f\u81ea\u8eab\u3092\u795e\u3060\u3068\u306f\u601d\u3063\u3066\u3044\u306a\u304b\u3063\u305f","permalink":"/ds/blog/2025/01/01/be_2"}}')}}]);